values (
  '914a4928-d9c0-4b8d-9017-66e0bc29b180',
  'KHC Mortgage Revenue Bond (MRB) Program',
  'Kentucky Housing Corporation',
  'rate_reduction',
  'Below-market-rate 30-year fixed first mortgage (FHA, VA, or RHS), funded through tax-exempt bond proceeds -- 5.750% per KHC''s current lender rate sheet, vs. 6.500%+ for KHC''s non-bond Secondary Market loans. Income and purchase-price limits are federally imposed (not KHC-set). First-time buyer required in most of Kentucky; waived entirely for both first-time and repeat buyers purchasing in one of KHC''s designated targeted census tracts. Can be paired with KHC''s Down Payment Assistance. NOTE: purchase price limit ($544,232) sourced from the MRB-specific income-limit PDF, distinct from the $566,354 figure on KHC''s general live Eligibility page (likely a different, non-MRB product max) -- flagged, not silently reused from the DPA/SAM entries.',
  'https://www.kyhousing.org/page/loan-programs',
  'open',
  current_date
);

;

-- ------------------------------------------------------------
-- Verification query
-- ------------------------------------------------------------
select p.name, r.rule_type, r.exempts_rule_id, r.evaluation_order,
       jsonb_pretty(r.rule_config) as rule_config
from programs p
join program_eligibility_rules r on r.program_id = p.id
where p.name = 'KHC Mortgage Revenue Bond (MRB) Program'
order by r.evaluation_order;

select count(*) as base_rows_inserted from geo_lookup_values
where lookup_table_id = 'f7d87969-86b7-4368-8787-d68fcf8d1a6f';

select count(*) as targeted_rows_inserted from geo_lookup_values
where lookup_table_id = 'f2f3fca1-e53c-4b98-a4a9-16ba393a0a95';